{
  "code": "600519.SH",
  "rebuttals": [
    {
      "target": "methods[0].assumptions.base_fcf_ttm_元",
      "attack": "该基期FCF 1167.3亿元对应TTM净利润约814.3亿元，FCF/净利润达1.43，显著高于1。过于依赖合同负债、预收或营运资本波动项，不代表经常性盈利现金流。估值方note已承认若营运资本波动导致均值回归，DCF会下修，但仍将1322元作为基准值，内部矛盾且高估。",
      "severity": "high"
    },
    {
      "target": "methods[0].assumptions.growth_cagr_10y",
      "attack": "2026-06-30单季净利润172.74亿元，同比下降约6.9%；估值方却假设未来10年FCF复合增长2%-4%。在高端白酒需求受政策、消费税和商务消费疲软影响下，缺乏量价证据支持持续正增长，低端2%本身已偏乐观。",
      "severity": "high"
    },
    {
      "target": "methods[0].assumptions.discount_rate",
      "attack": "10%折现率未提供推导依据，也未与无风险利率、股权风险溢价、资本成本做一致性说明。若考虑白酒政策风险、盈利下滑和治理信息缺失，当前折现率未必充分反映风险；折现率的小幅下调会显著抬高DCF结果。",
      "severity": "low"
    },
    {
      "target": "methods[0].assumptions.terminal_growth",
      "attack": "2%-3%永续增长隐含高端白酒长期可跑赢或持平名义GDP。考虑人口结构变化和白酒消费量长期萎缩，提价难以无限补偿，3%高端情景缺乏量化支撑，且与宏观潜在增速的审慎假设不一致。",
      "severity": "medium"
    },
    {
      "target": "methods[0].assumptions.net_cash_included",
      "attack": "DCF未包含净现金，而PB-ROE按账面价值包含净资产中的现金/金融资产，方法间不一致。若存在重大净现金，DCF应加回；若不重大，也需披露金额。当前处理使DCF估值口径不完整。",
      "severity": "low"
    },
    {
      "target": "methods[1].assumptions.ttm_eps",
      "attack": "TTM EPS 65.05元属于滞后指标。2026Q2单季净利润同比下滑6.9%，若该趋势延续，前瞻EPS将低于65.05元，按18倍PE计算价值会低于1171元。以TTM数据作为市盈率法唯一EPS输入会高估。",
      "severity": "medium"
    },
    {
      "target": "methods[1].assumptions.fair_pe",
      "attack": "18倍fair PE虽然低于当前20.25倍，但当前TTM PE处于72.4%历史分位，并不构成安全边际。历史上白酒下行周期龙头PE可跌至15倍以下；在单季净利润下滑、政策风险未消的背景下，16-20倍区间下限仍可能不保守。",
      "severity": "high"
    },
    {
      "target": "methods[1].assumptions.basis",
      "attack": "引用000858五粮液PE TTM 24.41作为同业锚存在问题：五粮液自身可能被高估，且品牌、渠道、治理不同。相对估值在行业景气下行期会系统性高估，不能作为18倍PE的支撑。",
      "severity": "medium"
    },
    {
      "target": "methods[2].assumptions.normalized_roe",
      "attack": "normalized ROE取28%仍偏高。ROE已从2024年36.02%降至2025年32.53%，下降3.49个百分点；2026Q2单季净利润同比下滑6.9%。若未来ROE向25%或更低回归，PB-ROE估值将明显下修。",
      "severity": "high"
    },
    {
      "target": "methods[2].assumptions.justified_pb",
      "attack": "纯数学justified PB仅为3.57，估值方以品牌护城河溢价为由上调至6.0，溢价约68%，但未给出模型、可比交易或量化依据。PB-ROE结果1206元高度依赖这一主观上调，缺乏稳健性。",
      "severity": "high"
    },
    {
      "target": "methods[2].assumptions.long_term_growth",
      "attack": "PB-ROE法采用3%永续增长，高于DCF法终端增长率基准2.5%，方法间假设不一致。对白酒长期产量萎缩品类，3%也偏乐观。",
      "severity": "medium"
    },
    {
      "target": "methods[2].assumptions.bps_latest",
      "attack": "BPS 200.9898元来自2026-06-30，但未考虑后续盈利下滑、分红或回购对净资产的影响。若ROE下降且分红率保持，BPS增速会低于3%，1206元对应的账面价值基础偏乐观。",
      "severity": "low"
    },
    {
      "target": "moat_evidence[0]",
      "attack": "毛利率并非稳定：从2025-06-30的91.30%降至2026-06-30的89.56%，下降1.74个百分点。单季净利润下滑6.9%，说明毛利率韧性正在被侵蚀，不能单独作为wide moat证据。",
      "severity": "medium"
    },
    {
      "target": "moat_evidence[1]",
      "attack": "ROE显著高于资本成本，但已从36.02%降至32.53%，显示盈利能力处于下行通道，不能直接外推为正常化28%仍可长期维持。",
      "severity": "medium"
    },
    {
      "target": "moat_evidence[2]",
      "attack": "FCF 1167.3亿元高于净利润814.3亿元，比例为1.43，明显偏离1：1常态，可能来自合同负债、预收或营运资本波动，不能作为可持续现金流护城河证据。",
      "severity": "high"
    },
    {
      "target": "moat_evidence[3]",
      "attack": "债务率12.12%与19.04%未给出定义，可能包含合同负债等经营性负债。即使资产负债率低，也只表明财务稳健，不构成宽护城河，无法抵消盈利下滑与FCF异常。",
      "severity": "low"
    },
    {
      "target": "moat_rating",
      "attack": "wide评级证据不足：毛利率、ROE、单季净利润均在下滑，缺少飞天茅台批价、渠道库存、预收/合同负债变化、提价能力等量化证据。wide moat被用于将PB从3.57上调至6.0，可能直接导致估值虚高。",
      "severity": "high"
    },
    {
      "target": "margin_of_safety",
      "attack": "安全边际-12.51%为负，但更关键问题是内在价值区间1171-1450元宽度约23.8%，上限依赖乐观假设。当前价1317.5元接近DCF基准值，下行风险大于上行，负安全边际仍不满足买入闸门。",
      "severity": "medium"
    }
  ],
  "fatal_issues": [
    "methods[0]使用FCF/NI=1.43的异常高基期FCF，且估值方自认营运资本波动可能导致均值回归；若FCF回归至净利润或低于净利润，DCF基准值1322元可能下修至1000元以下，使买入逻辑证伪。",
    "methods[2]将justified PB从纯数学3.57主观上调至6.0，溢价约68%，未提供量化依据；PB-ROE法1206元高度依赖该主观溢价，无法验证。",
    "最新单季净利润同比下滑6.9%，但所有方法假设未来正增长和高ROE（2%-4%增长、28%ROE、3%永续增长），前瞻假设与最新财务数据矛盾。"
  ],
  "verdict": "估值方给出的内在价值区间缺乏稳健性：DCF基期FCF不可持续，PB-ROE给予主观品牌溢价，市盈率法使用滞后EPS和偏乐观公平PE。近期盈利下滑与增长假设矛盾，当前1317.5元不满足安全边际要求。",
  "needs_data": [
    "历史FCF/净利润、经营现金流与合同负债/预收变化，判断FCF可持续性及营运资本影响",
    "分红率、回购、资本配置政策及公告摘要，确认股东回报与治理信号",
    "飞天茅台批价、渠道库存、预收/合同负债余额趋势，验证提价能力与需求",
    "白酒消费税政策及宏观/商务消费数据，评估政策与需求风险",
    "净现金及金融资产具体金额，统一DCF与PB-ROE口径",
    "2013-2014白酒下行周期茅台PE、ROE、毛利率表现，用于压力测试公平PE与ROE"
  ]
}
